// Package gzenv implements the encoding used by direnv to transport
// structured data through environment variables: JSON, compressed with zlib
// and encoded with URL-safe base64.
package gzenv

import (
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
)

// Marshal encodes the given value into the gzenv format.
func Marshal(obj interface{}) string {
	jsonData, err := json.Marshal(obj)
	if err != nil {
		panic(fmt.Sprintf("gzenv: marshal: %v", err))
	}

	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	if _, err = w.Write(jsonData); err != nil {
		panic(fmt.Sprintf("gzenv: compress: %v", err))
	}
	if err = w.Close(); err != nil {
		panic(fmt.Sprintf("gzenv: compress: %v", err))
	}

	return base64.URLEncoding.EncodeToString(buf.Bytes())
}

// Unmarshal decodes a gzenv formatted string into the given value.
func Unmarshal(data string, obj interface{}) error {
	zlibData, err := base64.URLEncoding.DecodeString(data)
	if err != nil {
		return fmt.Errorf("unmarshal() base64 decoding: %w", err)
	}

	r, err := zlib.NewReader(bytes.NewReader(zlibData))
	if err != nil {
		return fmt.Errorf("unmarshal() zlib opening: %w", err)
	}

	var buf bytes.Buffer
	if _, err = io.Copy(&buf, r); err != nil {
		return fmt.Errorf("unmarshal() zlib decoding: %w", err)
	}

	if err = json.Unmarshal(buf.Bytes(), obj); err != nil {
		return fmt.Errorf("unmarshal() json: %w", err)
	}

	return nil
}
EOF
echo ok"}

