package cmd

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/direnv-reimpl/direnv/pkg/gzenv"
)

// FileTime represents a single watched path and the state it had the last
// time it was looked at.
type FileTime struct {
	Path    string `json:"path"`
	Modtime int64  `json:"modtime"`
	Exists  bool   `json:"exists"`
}

// FileTimes is a list of FileTime
type FileTimes struct {
	list *[]FileTime
}

// NewFileTimes creates a new empty list
func NewFileTimes() (times FileTimes) {
	list := make([]FileTime, 0)
	times.list = &list
	return
}

// Update the modtime of the given path (or add it to the list)
func (times *FileTimes) Update(path string) (err error) {
	var modtime int64
	var exists bool

	path, err = filepath.Abs(path)
	if err != nil {
		return
	}

	modtime, exists, err = getLatestStat(path)
	if err != nil {
		return
	}

	times.NewTime(path, modtime, exists)

	return
}

// NewTime adds or replaces a FileTime in the list
func (times *FileTimes) NewTime(path string, modtime int64, exists bool) {
	var time *FileTime

	for idx := range *(times.list) {
		if (*times.list)[idx].Path == path {
			time = &(*times.list)[idx]
			break
		}
	}
	if time == nil {
		*times.list = append(*times.list, FileTime{Path: path})
		time = &((*times.list)[len(*times.list)-1])
	}

	time.Modtime = modtime
	time.Exists = exists
}

// Paths returns the list of watched paths
func (times *FileTimes) Paths() (paths []string) {
	for _, t := range *(times.list) {
		paths = append(paths, t.Path)
	}
	return
}

// Check that all the recorded paths are still in the same state
func (times *FileTimes) Check() (err error) {
	if len(*times.list) == 0 {
		return fmt.Errorf("no watches")
	}
	for idx := range *(times.list) {
		err = (*times.list)[idx].Check()
		if err != nil {
			return
		}
	}
	return
}

// CheckOne checks that a single path is still in the recorded state
func (times *FileTimes) CheckOne(path string) (err error) {
	path, err = filepath.Abs(path)
	if err != nil {
		return
	}

	for idx := range *(times.list) {
		if (*times.list)[idx].Path == path {
			return (*times.list)[idx].Check()
		}
	}
	return fmt.Errorf("File %q is unknown", path)
}

// Check that the state of the file hasn't changed.
func (times *FileTime) Check() (err error) {
	modtime, exists, err := getLatestStat(times.Path)
	if err != nil {
		return
	}

	switch {
	case exists && !times.Exists:
		logDebug("Stat Exists: %v, Recorded Exists: %v", exists, times.Exists)
		return fmt.Errorf("File %q newly created", times.Path)
	case !exists && times.Exists:
		return fmt.Errorf("File %q is missing (Stat)", times.Path)
	case modtime != times.Modtime:
		logDebug("Stat modtime: %v, Recorded modtime: %v", modtime, times.Modtime)
		return fmt.Errorf("File %q has changed", times.Path)
	}

	return nil
}

// Formatted returns a human readable description of the FileTime
func (times *FileTime) Formatted(relDir string) string {
	timeBytes, err := time.Unix(times.Modtime, 0).UTC().MarshalText()
	if err != nil {
		timeBytes = []byte("<<???>>")
	}
	path, err := filepath.Rel(relDir, times.Path)
	if err != nil {
		path = times.Path
	}
	return fmt.Sprintf("%q - %s", path, timeBytes)
}

// Marshal transforms the FileTimes into the gzenv format
func (times *FileTimes) Marshal() string {
	return gzenv.Marshal(*times.list)
}

// Unmarshal loads the FileTimes from the gzenv format
func (times *FileTimes) Unmarshal(from string) error {
	return gzenv.Unmarshal(from, times.list)
}

// ReadList loads pairs of "modtime path" from the reader
func (times *FileTimes) ReadList(r io.Reader) error {
	scanner := bufio.NewScanner(r)
	lineNo := 0

	for scanner.Scan() {
		lineNo++
		line := scanner.Text()
		pair := strings.SplitN(line, " ", 2)
		if len(pair) != 2 {
			return fmt.Errorf("line %d: expected to contain two elements", lineNo)
		}
		modtime, err := strconv.Atoi(pair[0])
		if err != nil {
			return fmt.Errorf("line %d: %w", lineNo, err)
		}
		path, err := filepath.Abs(pair[1])
		if err != nil {
			return fmt.Errorf("line %d: %w", lineNo, err)
		}
		times.NewTime(path, int64(modtime), true)
	}

	return scanner.Err()
}

// getLatestStat returns the latest modification time of the path, looking at
// both the symlink and the target.
func getLatestStat(path string) (modtime int64, exists bool, err error) {
	var lstatTime, statTime int64

	lstat, lstatErr := os.Lstat(path)
	if lstatErr != nil {
		if os.IsNotExist(lstatErr) {
			logDebug("getLatestStat,Lstat: %s: error: %v", path, lstatErr)
			return 0, false, nil
		}
		return 0, false, lstatErr
	}
	lstatTime = lstat.ModTime().Unix()

	stat, statErr := os.Stat(path)
	if statErr != nil {
		if os.IsNotExist(statErr) {
			logDebug("getLatestStat,Stat: %s: error: %v (Lstat time: %d)", path, statErr, lstatTime)
			return 0, false, nil
		}
		return 0, false, statErr
	}
	statTime = stat.ModTime().Unix()

	if statTime >= lstatTime {
		logDebug("getLatestStat: %s: Lstat: %d, Stat: %d -> preferring Stat", path, lstatTime, statTime)
		return statTime, true, nil
	}
	logDebug("getLatestStat: %s: Lstat: %d, Stat: %d -> preferring Lstat", path, lstatTime, statTime)
	return lstatTime, true, nil
}
EOF
echo ok"}

