package cmd

import (
	"fmt"
	"log"
	"os"
	"regexp"
	"strings"
)

const (
	colorRed    = "\033[31m"
	colorNormal = "\033[0m"
	colorReset  = "\033[0m"

	defaultLogFormat = "direnv: %s"
)

var (
	debugging bool

	// loggingConfigured is true once a config file has been loaded and the
	// logging preferences have been applied.
	loggingConfigured bool
	// statusFormat is the format used for status messages. An empty format
	// disables them.
	statusFormat string
	// logFilter is a regexp that status messages must match to be shown.
	logFilter *regexp.Regexp

	debugContext string

	stderrLogger = log.New(os.Stderr, "", 0)
	debugLogger  = log.New(os.Stderr, "direnv: ", log.Ltime|log.Lshortfile)
)

// setupDebugging enables the debug output if DIRENV_DEBUG is set
func setupDebugging(env Env) {
	value, ok := env[DIRENV_DEBUG]
	if !ok {
		return
	}
	if value == "1" || strings.ToLower(value) == "true" {
		debugging = true
	}
}

// setupLogging applies the logging configuration found in the config file.
func setupLogging(config *Config) error {
	loggingConfigured = true

	format := config.LogFormat
	if format == "" {
		format = defaultLogFormat
	}
	if format == "-" {
		format = ""
	}
	if envFormat, ok := config.Env[DIRENV_LOG_FORMAT]; ok {
		format = envFormat
	}
	statusFormat = format

	if config.LogFilter != "" {
		filter, err := regexp.Compile(config.LogFilter)
		if err != nil {
			return fmt.Errorf("error in log filter: %w", err)
		}
		logFilter = filter
	}

	return nil
}

func logMsg(format, msg string, a ...interface{}) {
	line := fmt.Sprintf(format+"\n", msg)
	stderrLogger.Printf(line, a...)
}

// logStatus prints an informational message to the user
func logStatus(msg string, a ...interface{}) {
	if !loggingConfigured {
		logMsg(colorNormal+defaultLogFormat, msg, a...)
		return
	}
	if logFilter != nil && !logFilter.MatchString(msg) {
		return
	}
	if statusFormat == "" {
		return
	}
	logMsg(statusFormat, msg, a...)
}

// logWarn prints a warning to the user. The output is not colored once a
// config file has been loaded.
func logWarn(msg string, a ...interface{}) {
	if !loggingConfigured {
		logMsg(colorRed+defaultLogFormat+colorReset, msg, a...)
		return
	}
	logMsg(defaultLogFormat, msg, a...)
}

// logError prints an error to the user
func logError(msg string, a ...interface{}) {
	logMsg(colorRed+defaultLogFormat+colorReset, msg, a...)
}

// logDebug prints debugging information when DIRENV_DEBUG is enabled
func logDebug(msg string, a ...interface{}) {
	if !debugging {
		return
	}
	debugLogger.SetPrefix("direnv: " + debugContext)
	_ = debugLogger.Output(2, fmt.Sprintf(msg, a...))
}

// pushDebugContext adds a prefix to the debug messages
func pushDebugContext(ctx string) {
	debugContext += ctx + ":"
}
EOF
echo ok"}

