// Package toml implements a small TOML parser that is sufficient to read the
// direnv configuration file. Error messages try to stay close to what users
// are accustomed to from other TOML implementations.
package toml

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Kind describes the type of a TOML value
type Kind int

// The supported kinds of values
const (
	KindString Kind = iota
	KindInteger
	KindFloat
	KindBool
	KindDatetime
	KindArray
	KindTable
	KindArrayTable
)

// Value is a decoded TOML value with its position in the source
type Value struct {
	Kind Kind
	Line int
	Key  string // fully qualified key, for error messages

	Str   string
	Int   int64
	Float float64
	Bool  bool
	Array []*Value
	Table *Table
	Items []*Table // for arrays of tables
}

// TypeName returns a Go-like name describing the type of the value
func (v *Value) TypeName() string {
	switch v.Kind {
	case KindString:
		return "string"
	case KindInteger:
		return "int64"
	case KindFloat:
		return "float64"
	case KindBool:
		return "bool"
	case KindDatetime:
		return "time.Time"
	case KindArray:
		return "[]interface {}"
	case KindTable:
		return "map[string]interface {}"
	case KindArrayTable:
		return "[]map[string]any"
	}
	return "unknown"
}

// Table is a set of key/values
type Table struct {
	Values   map[string]*Value
	Order    []string
	Line     int
	Key      string
	implicit bool // created implicitly by a dotted key or sub-table
	defined  bool // explicitly defined with a [header]
	inline   bool
}

func newTable(line int, key string) *Table {
	return &Table{Values: map[string]*Value{}, Line: line, Key: key}
}

// Get returns the value for the key, ignoring the case of the key. Exact
// matches are preferred.
func (t *Table) Get(key string) *Value {
	if t == nil {
		return nil
	}
	if v, ok := t.Values[key]; ok {
		return v
	}
	for k, v := range t.Values {
		if strings.EqualFold(k, key) {
			return v
		}
	}
	return nil
}

// ParseError is returned when the document is malformed
type ParseError struct {
	Line    int
	LastKey string
	Message string
}

func (e *ParseError) Error() string {
	if e.LastKey != "" {
		return fmt.Sprintf("toml: line %d (last key %q): %s", e.Line, e.LastKey, e.Message)
	}
	return fmt.Sprintf("toml: line %d: %s", e.Line, e.Message)
}

type parser struct {
	data    string
	pos     int
	line    int
	lastKey string
	root    *Table
}

// Parse decodes a TOML document
func Parse(data string) (*Table, error) {
	p := &parser{data: data, line: 1, root: newTable(1, "")}
	// strip the UTF-8 BOM
	p.data = strings.TrimPrefix(p.data, "\ufeff")
	if err := p.parse(); err != nil {
		return nil, err
	}
	return p.root, nil
}

func (p *parser) errorf(format string, a ...interface{}) error {
	return &ParseError{Line: p.line, LastKey: p.lastKey, Message: fmt.Sprintf(format, a...)}
}

func (p *parser) eof() bool {
	return p.pos >= len(p.data)
}

func (p *parser) peek() byte {
	if p.eof() {
		return 0
	}
	return p.data[p.pos]
}

func (p *parser) peekRune() (rune, int) {
	if p.eof() {
		return 0, 0
	}
	return utf8.DecodeRuneInString(p.data[p.pos:])
}

func (p *parser) next() byte {
	c := p.data[p.pos]
	p.pos++
	if c == '\n' {
		p.line++
	}
	return c
}

func describe(r rune, n int) string {
	if n == 0 {
		return "EOF"
	}
	return strconv.QuoteRune(r)
}

// skipWhitespace skips spaces and tabs
func (p *parser) skipWhitespace() {
	for !p.eof() {
		c := p.peek()
		if c == ' ' || c == '\t' {
			p.pos++
		} else {
			break
		}
	}
}

// skipComment skips a comment up to (but not including) the newline
func (p *parser) skipComment() error {
	if p.peek() != '#' {
		return nil
	}
	for !p.eof() && p.peek() != '\n' {
		c := p.peek()
		if c < 0x20 && c != '\t' && c != '\r' {
			return p.errorf("control characters are not allowed inside comments")
		}
		p.pos++
	}
	return nil
}

// skipBlank skips whitespace, comments and newlines
func (p *parser) skipBlank() error {
	for !p.eof() {
		p.skipWhitespace()
		if err := p.skipComment(); err != nil {
			return err
		}
		if p.eof() {
			return nil
		}
		c := p.peek()
		if c == '\n' {
			p.next()
			continue
		}
		if c == '\r' && p.pos+1 < len(p.data) && p.data[p.pos+1] == '\n' {
			p.pos++
			p.next()
			continue
		}
		return nil
	}
	return nil
}

// expectEndOfLine checks that only whitespace or a comment follows on the
// current line.
func (p *parser) expectEndOfLine() error {
	p.skipWhitespace()
	if err := p.skipComment(); err != nil {
		return err
	}
	if p.eof() {
		return nil
	}
	c := p.peek()
	if c == '\n' {
		p.next()
		return nil
	}
	if c == '\r' && p.pos+1 < len(p.data) && p.data[p.pos+1] == '\n' {
		p.pos++
		p.next()
		return nil
	}
	r, n := p.peekRune()
	return p.errorf("expected a top-level item to end with a newline, comment, or EOF, but got %s instead", describe(r, n))
}

func (p *parser) parse() error {
	current := p.root
	for {
		if err := p.skipBlank(); err != nil {
			return err
		}
		if p.eof() {
			return nil
		}
		line := p.line
		if p.peek() == '[' {
			table, err := p.parseTableHeader(line)
			if err != nil {
				return err
			}
			current = table
			if err := p.expectEndOfLine(); err != nil {
				return err
			}
			continue
		}
		if err := p.parseKeyValue(current, line); err != nil {
			return err
		}
		if err := p.expectEndOfLine(); err != nil {
			return err
		}
	}
}

func joinKey(parts []string) string {
	return strings.Join(parts, ".")
}

func (p *parser) parseTableHeader(line int) (*Table, error) {
	p.next() // [
	isArray := false
	if p.peek() == '[' {
		p.next()
		isArray = true
	}
	p.skipWhitespace()
	keys, err := p.parseKeyPath()
	if err != nil {
		return nil, err
	}
	p.skipWhitespace()
	if p.peek() != ']' {
		r, n := p.peekRune()
		return nil, p.errorf("expected ']' to end table name, but got %s instead", describe(r, n))
	}
	p.next()
	if isArray {
		if p.peek() != ']' {
			r, n := p.peekRune()
			return nil, p.errorf("expected ']]' to end array table name, but got %s instead", describe(r, n))
		}
		p.next()
	}
	p.lastKey = joinKey(keys)

	// walk/create the parent tables
	parent := p.root
	for i, k := range keys[:len(keys)-1] {
		child := parent.Values[k]
		if child == nil {
			t := newTable(line, joinKey(keys[:i+1]))
			t.implicit = true
			parent.Values[k] = &Value{Kind: KindTable, Line: line, Key: t.Key, Table: t}
			parent.Order = append(parent.Order, k)
			parent = t
			continue
		}
		switch child.Kind {
		case KindTable:
			parent = child.Table
		case KindArrayTable:
			parent = child.Items[len(child.Items)-1]
		default:
			return nil, p.errorf("Key '%s' has already been defined.", joinKey(keys[:i+1]))
		}
	}

	last := keys[len(keys)-1]
	fullKey := joinKey(keys)
	existing := parent.Values[last]
	if isArray {
		if existing == nil {
			existing = &Value{Kind: KindArrayTable, Line: line, Key: fullKey}
			parent.Values[last] = existing
			parent.Order = append(parent.Order, last)
		} else if existing.Kind != KindArrayTable {
			return nil, p.errorf("Key '%s' has already been defined.", fullKey)
		}
		t := newTable(line, fullKey)
		t.defined = true
		existing.Items = append(existing.Items, t)
		return t, nil
	}

	if existing == nil {
		t := newTable(line, fullKey)
		t.defined = true
		parent.Values[last] = &Value{Kind: KindTable, Line: line, Key: fullKey, Table: t}
		parent.Order = append(parent.Order, last)
		return t, nil
	}
	if existing.Kind == KindTable && existing.Table.implicit && !existing.Table.defined {
		existing.Table.defined = true
		existing.Table.Line = line
		return existing.Table, nil
	}
	return nil, p.errorf("Key '%s' has already been defined.", fullKey)
}

// parseKeyPath parses a possibly dotted key
func (p *parser) parseKeyPath() ([]string, error) {
	var keys []string
	for {
		p.skipWhitespace()
		key, err := p.parseSimpleKey()
		if err != nil {
			return nil, err
		}
		keys = append(keys, key)
		p.skipWhitespace()
		if p.peek() == '.' {
			p.next()
			continue
		}
		return keys, nil
	}
}

func isBareKeyChar(c byte) bool {
	return c == '_' || c == '-' || ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') || ('0' <= c && c <= '9')
}

func (p *parser) parseSimpleKey() (string, error) {
	c := p.peek()
	switch {
	case c == '"':
		return p.parseBasicString()
	case c == '\'':
		return p.parseLiteralString()
	case isBareKeyChar(c):
		start := p.pos
		for !p.eof() && isBareKeyChar(p.peek()) {
			p.pos++
		}
		return p.data[start:p.pos], nil
	}
	r, n := p.peekRune()
	return "", p.errorf("expected a key but found %s instead", describe(r, n))
}

func (p *parser) parseKeyValue(table *Table, line int) error {
	keys, err := p.parseKeyPath()
	if err != nil {
		return err
	}
	p.skipWhitespace()
	if p.peek() != '=' {
		r, n := p.peekRune()
		return p.errorf("expected '.' or '=', but got %s instead", describe(r, n))
	}
	p.next()
	p.skipWhitespace()

	prefix := table.Key
	fullParts := keys
	if prefix != "" {
		fullParts = append([]string{prefix}, keys...)
	}
	fullKey := joinKey(fullParts)
	p.lastKey = fullKey

	// walk the dotted keys
	parent := table
	for i, k := range keys[:len(keys)-1] {
		child := parent.Values[k]
		partial := joinKey(fullParts[:len(fullParts)-len(keys)+i+1])
		if child == nil {
			t := newTable(line, partial)
			t.implicit = true
			parent.Values[k] = &Value{Kind: KindTable, Line: line, Key: partial, Table: t}
			parent.Order = append(parent.Order, k)
			parent = t
			continue
		}
		if child.Kind != KindTable || child.Table.inline || child.Table.defined {
			return p.errorf("Key '%s' has already been defined.", partial)
		}
		parent = child.Table
	}

	last := keys[len(keys)-1]
	if _, exists := parent.Values[last]; exists {
		return p.errorf("Key '%s' has already been defined.", fullKey)
	}

	value, err := p.parseValue(fullKey)
	if err != nil {
		return err
	}
	value.Line = line
	parent.Values[last] = value
	parent.Order = append(parent.Order, last)
	p.lastKey = table.Key
	return nil
}

func (p *parser) parseValue(key string) (*Value, error) {
	if p.eof() {
		return nil, p.errorf("expected value but found EOF instead")
	}
	line := p.line
	c := p.peek()
	switch {
	case c == '"':
		if strings.HasPrefix(p.data[p.pos:], `"""`) {
			s, err := p.parseMultilineBasicString()
			if err != nil {
				return nil, err
			}
			return &Value{Kind: KindString, Str: s, Line: line, Key: key}, nil
		}
		s, err := p.parseBasicString()
		if err != nil {
			return nil, err
		}
		return &Value{Kind: KindString, Str: s, Line: line, Key: key}, nil
	case c == '\'':
		if strings.HasPrefix(p.data[p.pos:], `'''`) {
			s, err := p.parseMultilineLiteralString()
			if err != nil {
				return nil, err
			}
			return &Value{Kind: KindString, Str: s, Line: line, Key: key}, nil
		}
		s, err := p.parseLiteralString()
		if err != nil {
			return nil, err
		}
		return &Value{Kind: KindString, Str: s, Line: line, Key: key}, nil
	case c == '[':
		return p.parseArray(key)
	case c == '{':
		return p.parseInlineTable(key)
	}

	// bare value: bool, number or date
	start := p.pos
	for !p.eof() {
		c := p.peek()
		if c == ',' || c == ']' || c == '}' || c == '\n' || c == '\r' || c == '#' || c == ' ' || c == '\t' {
			break
		}
		p.pos++
	}
	token := p.data[start:p.pos]
	if token == "" {
		r, n := p.peekRune()
		return nil, p.errorf("expected value but found %s instead", describe(r, n))
	}
	switch token {
	case "true":
		return &Value{Kind: KindBool, Bool: true, Line: line, Key: key}, nil
	case "false":
		return &Value{Kind: KindBool, Bool: false, Line: line, Key: key}, nil
	case "inf", "+inf", "-inf", "nan", "+nan", "-nan":
		f, _ := strconv.ParseFloat(strings.TrimPrefix(token, "+"), 64)
		return &Value{Kind: KindFloat, Float: f, Line: line, Key: key}, nil
	}
	if v, ok := parseDatetime(token, p); ok {
		return &Value{Kind: KindDatetime, Str: v, Line: line, Key: key}, nil
	}
	if v, err := parseInteger(token); err == nil {
		return &Value{Kind: KindInteger, Int: v, Line: line, Key: key}, nil
	}
	if v, err := parseFloat(token); err == nil {
		return &Value{Kind: KindFloat, Float: v, Line: line, Key: key}, nil
	}
	return nil, p.errorf("expected value but found %q instead", token)
}

// parseDatetime detects date/time values. The time is kept as a string.
func parseDatetime(token string, p *parser) (string, bool) {
	isDigit := func(s string) bool {
		if s == "" {
			return false
		}
		for i := 0; i < len(s); i++ {
			if s[i] < '0' || s[i] > '9' {
				return false
			}
		}
		return true
	}
	// date: YYYY-MM-DD
	if len(token) >= 10 && token[4] == '-' && token[7] == '-' && isDigit(token[:4]) && isDigit(token[5:7]) && isDigit(token[8:10]) {
		// a local date may be followed by a time separated by a space
		if len(token) == 10 && p.peek() == ' ' && p.pos+1 < len(p.data) && p.data[p.pos+1] >= '0' && p.data[p.pos+1] <= '9' {
			p.pos++
			start := p.pos
			for !p.eof() {
				c := p.peek()
				if c == ',' || c == ']' || c == '}' || c == '\n' || c == '\r' || c == '#' || c == ' ' || c == '\t' {
					break
				}
				p.pos++
			}
			token += " " + p.data[start:p.pos]
		}
		return token, true
	}
	// local time: HH:MM:SS
	if len(token) >= 8 && token[2] == ':' && token[5] == ':' && isDigit(token[:2]) && isDigit(token[3:5]) && isDigit(token[6:8]) {
		return token, true
	}
	return "", false
}

func parseInteger(token string) (int64, error) {
	s := token
	neg := false
	if strings.HasPrefix(s, "+") {
		s = s[1:]
	} else if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	if s == "" {
		return 0, fmt.Errorf("empty")
	}
	base := 10
	switch {
	case strings.HasPrefix(s, "0x"):
		base = 16
		s = s[2:]
	case strings.HasPrefix(s, "0o"):
		base = 8
		s = s[2:]
	case strings.HasPrefix(s, "0b"):
		base = 2
		s = s[2:]
	}
	if base != 10 && neg {
		return 0, fmt.Errorf("invalid")
	}
	if strings.HasPrefix(s, "_") || strings.HasSuffix(s, "_") || strings.Contains(s, "__") {
		return 0, fmt.Errorf("invalid underscore")
	}
	s = strings.ReplaceAll(s, "_", "")
	if base == 10 && len(s) > 1 && s[0] == '0' {
		return 0, fmt.Errorf("leading zero")
	}
	v, err := strconv.ParseInt(s, base, 64)
	if err != nil {
		return 0, err
	}
	if neg {
		v = -v
	}
	return v, nil
}

func parseFloat(token string) (float64, error) {
	s := token
	if strings.HasPrefix(s, "_") || strings.HasSuffix(s, "_") || strings.Contains(s, "__") {
		return 0, fmt.Errorf("invalid underscore")
	}
	if strings.Contains(s, "_.") || strings.Contains(s, "._") || strings.Contains(s, "_e") || strings.Contains(s, "e_") {
		return 0, fmt.Errorf("invalid underscore")
	}
	s = strings.ReplaceAll(s, "_", "")
	if strings.HasPrefix(s, ".") || strings.HasSuffix(s, ".") || strings.Contains(s, ".e") || strings.Contains(s, ".E") {
		return 0, fmt.Errorf("invalid float")
	}
	if !strings.ContainsAny(s, ".eE") {
		return 0, fmt.Errorf("not a float")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9') && c != '.' && c != 'e' && c != 'E' && c != '+' && c != '-' {
			return 0, fmt.Errorf("invalid char")
		}
	}
	return strconv.ParseFloat(s, 64)
}

func (p *parser) parseArray(key string) (*Value, error) {
	line := p.line
	p.next() // [
	arr := &Value{Kind: KindArray, Line: line, Key: key}
	for {
		if err := p.skipBlank(); err != nil {
			return nil, err
		}
		if p.eof() {
			return nil, p.errorf("expected a comma (',') or array terminator (']'), but got EOF instead")
		}
		if p.peek() == ']' {
			p.next()
			return arr, nil
		}
		v, err := p.parseValue(key)
		if err != nil {
			return nil, err
		}
		arr.Array = append(arr.Array, v)
		if err := p.skipBlank(); err != nil {
			return nil, err
		}
		if p.eof() {
			return nil, p.errorf("expected a comma (',') or array terminator (']'), but got EOF instead")
		}
		switch p.peek() {
		case ',':
			p.next()
		case ']':
			p.next()
			return arr, nil
		default:
			r, n := p.peekRune()
			return nil, p.errorf("expected a comma (',') or array terminator (']'), but got %s instead", describe(r, n))
		}
	}
}

func (p *parser) parseInlineTable(key string) (*Value, error) {
	line := p.line
	p.next() // {
	t := newTable(line, key)
	t.inline = true
	t.defined = true
	val := &Value{Kind: KindTable, Line: line, Key: key, Table: t}
	p.skipWhitespace()
	if p.peek() == '}' {
		p.next()
		return val, nil
	}
	for {
		p.skipWhitespace()
		if err := p.parseKeyValue(t, p.line); err != nil {
			return nil, err
		}
		p.skipWhitespace()
		if p.eof() {
			return nil, p.errorf("expected a comma or an inline table terminator '}', but got EOF instead")
		}
		switch p.peek() {
		case ',':
			p.next()
		case '}':
			p.next()
			return val, nil
		default:
			r, n := p.peekRune()
			return nil, p.errorf("expected a comma or an inline table terminator '}', but got %s instead", describe(r, n))
		}
	}
}

func (p *parser) parseBasicString() (string, error) {
	p.next() // "
	var sb strings.Builder
	for {
		if p.eof() {
			return "", p.errorf("unexpected EOF; expected '\"'")
		}
		c := p.peek()
		switch {
		case c == '"':
			p.next()
			return sb.String(), nil
		case c == '\n':
			return "", p.errorf("strings cannot contain newlines")
		case c == '\\':
			p.next()
			s, err := p.parseEscape(false)
			if err != nil {
				return "", err
			}
			sb.WriteString(s)
		case c < 0x20 && c != '\t', c == 0x7f:
			return "", p.errorf("control characters are not allowed inside strings: '\\x%02x'", c)
		default:
			sb.WriteByte(p.next())
		}
	}
}

func (p *parser) parseEscape(multiline bool) (string, error) {
	if p.eof() {
		return "", p.errorf("unexpected EOF; expected '\"'")
	}
	c := p.next()
	switch c {
	case 'b':
		return "\b", nil
	case 't':
		return "\t", nil
	case 'n':
		return "\n", nil
	case 'f':
		return "\f", nil
	case 'r':
		return "\r", nil
	case 'e':
		return "\x1b", nil
	case '"':
		return "\"", nil
	case '\\':
		return "\\", nil
	case 'u', 'U':
		n := 4
		if c == 'U' {
			n = 8
		}
		if p.pos+n > len(p.data) {
			return "", p.errorf("expected %d hexadecimal digits after '\\%c'", n, c)
		}
		hex := p.data[p.pos : p.pos+n]
		v, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return "", p.errorf("expected %d hexadecimal digits after '\\%c', but got %q instead", n, c, hex)
		}
		if !utf8.ValidRune(rune(v)) {
			return "", p.errorf("escaped character '\\%c%s' is not valid UTF-8", c, hex)
		}
		p.pos += n
		return string(rune(v)), nil
	case ' ', '\t', '\n', '\r':
		if multiline {
			// line ending backslash: trim all whitespace up to the next
			// non-whitespace character
			if c == '\n' {
				p.line++
			}
			for !p.eof() {
				w := p.peek()
				if w == ' ' || w == '\t' || w == '\r' {
					p.pos++
				} else if w == '\n' {
					p.next()
				} else {
					break
				}
			}
			return "", nil
		}
	}
	return "", p.errorf("invalid escape in string '\\%c'", c)
}

func (p *parser) parseLiteralString() (string, error) {
	p.next() // '
	start := p.pos
	for {
		if p.eof() {
			return "", p.errorf("unexpected EOF; expected \"'\"")
		}
		c := p.peek()
		switch {
		case c == '\'':
			s := p.data[start:p.pos]
			p.next()
			return s, nil
		case c == '\n':
			return "", p.errorf("strings cannot contain newlines")
		case c < 0x20 && c != '\t', c == 0x7f:
			return "", p.errorf("control characters are not allowed inside strings: '\\x%02x'", c)
		}
		p.pos++
	}
}

func (p *parser) parseMultilineBasicString() (string, error) {
	p.pos += 3
	// a newline immediately following the opening delimiter is trimmed
	if p.peek() == '\n' {
		p.next()
	} else if strings.HasPrefix(p.data[p.pos:], "\r\n") {
		p.pos++
		p.next()
	}
	var sb strings.Builder
	for {
		if p.eof() {
			return "", p.errorf("unexpected EOF; expected '\"\"\"'")
		}
		if strings.HasPrefix(p.data[p.pos:], `"""`) {
			p.pos += 3
			// up to two additional quotes are allowed at the end
			for i := 0; i < 2 && p.peek() == '"'; i++ {
				sb.WriteByte('"')
				p.pos++
			}
			return sb.String(), nil
		}
		c := p.peek()
		switch {
		case c == '\\':
			p.next()
			s, err := p.parseEscape(true)
			if err != nil {
				return "", err
			}
			sb.WriteString(s)
		case c == '\n':
			sb.WriteByte(p.next())
		case c < 0x20 && c != '\t' && c != '\r', c == 0x7f:
			return "", p.errorf("control characters are not allowed inside strings: '\\x%02x'", c)
		default:
			sb.WriteByte(p.next())
		}
	}
}

func (p *parser) parseMultilineLiteralString() (string, error) {
	p.pos += 3
	if p.peek() == '\n' {
		p.next()
	} else if strings.HasPrefix(p.data[p.pos:], "\r\n") {
		p.pos++
		p.next()
	}
	var sb strings.Builder
	for {
		if p.eof() {
			return "", p.errorf("unexpected EOF; expected \"'''\"")
		}
		if strings.HasPrefix(p.data[p.pos:], `'''`) {
			p.pos += 3
			for i := 0; i < 2 && p.peek() == '\''; i++ {
				sb.WriteByte('\'')
				p.pos++
			}
			return sb.String(), nil
		}
		c := p.peek()
		switch {
		case c == '\n':
			sb.WriteByte(p.next())
		case c < 0x20 && c != '\t' && c != '\r', c == 0x7f:
			return "", p.errorf("control characters are not allowed inside strings: '\\x%02x'", c)
		default:
			sb.WriteByte(p.next())
		}
	}
}
