	}
	return nil, fmt.Errorf("Revert() failed: %w", err)
}

// loadToml reads and decodes the configuration file
func loadToml(path string, global *tomlGlobal, whitelist *tomlWhitelist) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	root, err := toml.Parse(string(data))
	if err != nil {
		return err
	}

	// the global settings can either be at the top-level or in the [global]
	// table
	if err := decodeGlobal(root, global); err != nil {
		return err
	}
	if v := root.Get("global"); v != nil {
		if v.Kind != toml.KindTable {
			return decodeError(v, "type mismatch for cmd.tomlGlobal: expected table but found "+v.TypeName())
		}
		if err := decodeGlobal(v.Table, global); err != nil {
			return err
		}
	}

	if v := root.Get("whitelist"); v != nil {
		if v.Kind != toml.KindTable {
			return decodeError(v, "type mismatch for cmd.tomlWhitelist: expected table but found "+v.TypeName())
		}
		var err error
		if whitelist.Prefix, err = decodeStringSlice(v.Table.Get("prefix")); err != nil {
			return err
		}
		if whitelist.Exact, err = decodeStringSlice(v.Table.Get("exact")); err != nil {
			return err
		}
	}

	return nil
}

func decodeGlobal(t *toml.Table, global *tomlGlobal) (err error) {
	if global.BashPath, err = decodeString(t.Get("bash_path"), global.BashPath); err != nil {
		return
	}
	if global.DisableStdin, err = decodeBool(t.Get("disable_stdin"), global.DisableStdin); err != nil {
		return
	}
	if global.StrictEnv, err = decodeBool(t.Get("strict_env"), global.StrictEnv); err != nil {
		return
	}
	if global.SkipDotenv, err = decodeBool(t.Get("skip_dotenv"), global.SkipDotenv); err != nil {
		return
	}
	if global.LoadDotenv, err = decodeBool(t.Get("load_dotenv"), global.LoadDotenv); err != nil {
		return
	}
	if global.WarnTimeout, err = decodeDuration(t.Get("warn_timeout"), global.WarnTimeout); err != nil {
		return
	}
	if global.HideEnvDiff, err = decodeBool(t.Get("hide_env_diff"), global.HideEnvDiff); err != nil {
		return
	}
	if global.LogFormat, err = decodeString(t.Get("log_format"), global.LogFormat); err != nil {
		return
	}
	if global.LogFilter, err = decodeString(t.Get("log_filter"), global.LogFilter); err != nil {
		return
	}
	return nil
}

func decodeError(v *toml.Value, msg string) error {
	return &toml.ParseError{Line: v.Line, LastKey: v.Key, Message: msg}
}

func incompatibleTypes(v *toml.Value, dest string) error {
	return decodeError(v, fmt.Sprintf("incompatible types: TOML value has type %s; destination has type %s", v.TypeName(), dest))
}

func decodeString(v *toml.Value, def string) (string, error) {
	if v == nil {
		return def, nil
	}
	if v.Kind != toml.KindString {
		return def, incompatibleTypes(v, "string")
	}
	return v.Str, nil
}

func decodeBool(v *toml.Value, def bool) (bool, error) {
	if v == nil {
		return def, nil
	}
	if v.Kind != toml.KindBool {
		return def, incompatibleTypes(v, "boolean")
	}
	return v.Bool, nil
}

func decodeDuration(v *toml.Value, def time.Duration) (time.Duration, error) {
	if v == nil {
		return def, nil
	}
	var str string
	switch v.Kind {
	case toml.KindString:
		str = v.Str
	case toml.KindInteger:
		str = fmt.Sprintf("%d", v.Int)
	case toml.KindFloat:
		str = fmt.Sprintf("%v", v.Float)
	default:
		return def, incompatibleTypes(v, "int64")
	}
	d, err := time.ParseDuration(str)
	if err != nil {
		return def, decodeError(v, err.Error())
	}
	return d, nil
}

func decodeStringSlice(v *toml.Value) ([]string, error) {
	if v == nil {
		return nil, nil
	}
	if v.Kind != toml.KindArray {
		return nil, incompatibleTypes(v, "slice")
	}
	out := make([]string, 0, len(v.Array))
	for _, item := range v.Array {
		if item.Kind != toml.KindString {
			return nil, incompatibleTypes(item, "string")
		}
		out = append(out, item.Str)
	}
	return out, nil
}
