package cmd

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"syscall"
)

// CmdExec is `direnv exec DIR <COMMAND> ...<ARGS>`
var CmdExec = &Cmd{
	Name: "exec",
	Desc: "Executes a command after loading the first .envrc or .env found in DIR",
	Args: []string{"DIR", "COMMAND", "[...ARGS]"},
	Action: actionWithConfig(func(env Env, args []string, config *Config) (err error) {
		var (
			newEnv Env
			rcPath string
			command string
		)

		if len(args) < 2 {
			return fmt.Errorf("missing DIR and COMMAND arguments")
		}

		rcPath = filepath.Clean(args[1])
		fi, err := os.Stat(rcPath)
		if err != nil {
			return err
		}

		if fi.IsDir() {
			if len(args) < 3 {
				return fmt.Errorf("missing COMMAND argument")
			}
			command = args[2]
			args = args[3:]
		} else {
			command = rcPath
			rcPath = filepath.Dir(rcPath)
			args = args[2:]
		}

		rcPath, err = filepath.Abs(rcPath)
		if err != nil {
			return err
		}

		rc, err := FindRC(rcPath, config)
		if err != nil {
			return err
		}

		// Restore pristine environment if needed
		newEnv, err = config.Revert(env)
		if err != nil {
			return err
		}
		newEnv.CleanContext()

		// Load the rc
		if rc != nil {
			newEnv, err = rc.Load(newEnv)
			if err != nil {
				return err
			}

			diff := env.Diff(newEnv)
			if diff.Any() {
				newEnv[DIRENV_DIFF] = diff.Serialize()
			}
