		if err != nil {
			return fmt.Errorf("command '%s' not found on PATH '%s'", command, newEnv["PATH"])
		}

		execArgs := append([]string{commandPath}, args...)
		err = syscall.Exec(commandPath, execArgs, newEnv.ToGoEnv())
		return
	}),
}

// lookPath searches for an executable named file in the directories of the
// given PATH string.
func lookPath(file, path string) (string, error) {
	if path == "" {
		return exec.LookPath(file)
	}
	oldPath := os.Getenv("PATH")
	defer func() { _ = os.Setenv("PATH", oldPath) }()
	if err := os.Setenv("PATH", path); err != nil {
		return "", err
	}
	return exec.LookPath(file)
}
