package cmd

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// CmdAllow is `direnv allow [PATH_TO_RC]`
var CmdAllow = &Cmd{
	Name:    "allow",
	Desc:    "Grants direnv permission to load the given .envrc or .env file.",
	Args:    []string{"[PATH_TO_RC]"},
	Aliases: []string{"permit", "grant"},
	Action: actionWithConfig(func(env Env, args []string, config *Config) (err error) {
		rc, err := findRCFromArgs(args, config)
		if err != nil {
			return err
		}

		if err = rc.Allow(); err != nil {
			return err
		}

		// Also approve the files listed in DIRENV_REQUIRED
		return allowRequiredFiles(env, rc, config)
	}),
}

// CmdDeny is `direnv deny [PATH_TO_RC]`
var CmdDeny = &Cmd{
	Name:    "block",
	Desc:    "Revokes the authorization of a given .envrc or .env file.",
	Args:    []string{"[PATH_TO_RC]"},
	Aliases: []string{"deny", "disallow", "revoke"},
	Action: actionWithConfig(func(env Env, args []string, config *Config) (err error) {
		rc, err := findRCFromArgs(args, config)
		if err != nil {
			return err
		}
		return rc.Deny()
	}),
}

// findRCFromArgs looks for the RC file to operate on. If a path is given, the
// search starts from that directory (or the directory of the given file).
func findRCFromArgs(args []string, config *Config) (*RC, error) {
	var rcPath string

	if len(args) > 1 {
		rcPath = args[1]
		fi, err := os.Lstat(rcPath)
		if err != nil {
			return nil, err
		}
		if !fi.IsDir() {
			rcPath = filepath.Dir(rcPath)
		}
		if rcPath, err = filepath.Abs(rcPath); err != nil {
			return nil, err
		}
	} else {
		rcPath = config.WorkDir
	}

	rc, err := FindRC(rcPath, config)
	if err != nil {
		return nil, err
	}
	if rc == nil {
		return nil, fmt.Errorf(".envrc file not found")
	}
	return rc, nil
}

// allowRequiredFiles records the approval of the files listed in the
// DIRENV_REQUIRED variable.
func allowRequiredFiles(env Env, rc *RC, config *Config) error {
	required := env[DIRENV_REQUIRED]
	if required == "" {
		return nil
	}

	envrcDir := filepath.Dir(rc.path)
	envrcHash, err := pathHash(rc.path)
	if err != nil {
		return err
	}
	dbDir := filepath.Join(config.AllowedRequiredDir(), envrcHash)

	for _, relPath := range strings.Split(required, ":") {
		absPath := filepath.Join(envrcDir, relPath)
		if _, err := os.Stat(absPath); err != nil {
			return fmt.Errorf("required file does not exist: %s", relPath)
		}

		hash, err := fileHash(absPath)
		if err != nil {
			return fmt.Errorf("failed to hash required file %s: %w", relPath, err)
		}

		if err := os.MkdirAll(dbDir, 0755); err != nil {
			return err
		}

		logStatus("allowing %s", relPath)
		if err := os.WriteFile(filepath.Join(dbDir, hash), []byte(relPath+"\n"), 0644); err != nil {
			return err
		}
	}

	return nil
}
EOF
