	"strings"
)

// CmdPrune is `direnv prune`
var CmdPrune = &Cmd{
	Name: "prune",
	Desc: "Removes old allowed and required files",
	Action: actionWithConfig(func(env Env, args []string, config *Config) (err error) {
		validEnvrcs := make(map[string]string) // path hash -> envrc path

		entries, err := os.ReadDir(config.AllowDir())
		if err != nil {
			if os.IsNotExist(err) {
				err = nil
			} else {
				return err
			}
		}

		for _, entry := range entries {
			if entry.IsDir() {
				continue
			}
			allowFile := filepath.Join(config.AllowDir(), entry.Name())
			data, readErr := os.ReadFile(allowFile)
			if readErr != nil {
				continue
			}
			envrc := strings.SplitN(string(data), "\n", 2)[0]
			if envrc == "" {
				continue
			}

			if !fileExists(envrc) {
				if err = os.Remove(allowFile); err != nil {
					return err
				}
				continue
			}

			hash, hashErr := fileHash(envrc)
			if hashErr != nil || hash != entry.Name() {
				if err = os.Remove(allowFile); err != nil {
					return err
				}
				continue
			}

			if ph, phErr := pathHash(envrc); phErr == nil {
				validEnvrcs[ph] = envrc
			}
		}

		// Prune the required files database
		requiredDir := config.AllowedRequiredDir()
		dirs, err := os.ReadDir(requiredDir)
		if err != nil {
			if os.IsNotExist(err) {
				return nil
			}
			return err
		}

		for _, dir := range dirs {
			dirPath := filepath.Join(requiredDir, dir.Name())
			envrc, ok := validEnvrcs[dir.Name()]
			if !ok {
				if err = os.RemoveAll(dirPath); err != nil {
					return err
				}
				continue
			}
			envrcDir := filepath.Dir(envrc)

			files, readErr := os.ReadDir(dirPath)
			if readErr != nil {
				continue
			}
			for _, file := range files {
				if file.IsDir() {
					continue
				}
				filePath := filepath.Join(dirPath, file.Name())
				data, readErr := os.ReadFile(filePath)
				if readErr != nil {
					continue
				}
				relPath := strings.TrimSpace(string(data))
				absPath := filepath.Join(envrcDir, relPath)

				if !fileExists(absPath) {
					if err = os.Remove(filePath); err != nil {
						return err
					}
					continue
				}

				hash, hashErr := fileHash(absPath)
				if hashErr != nil || hash != file.Name() {
					if err = os.Remove(filePath); err != nil {
						return err
					}
				}
			}
		}

		return nil
	}),
}
