// Package sri implements the W3C Subresource Integrity hash format
// (see https://www.w3.org/TR/SRI/).
package sri

import (
	"crypto/sha256"
	"crypto/sha512"
	"encoding/base64"
	"fmt"
	"hash"
	"strings"
)

// Algo is a supported hashing algorithm
type Algo string

// The supported algorithms
const (
	SHA256 Algo = "sha256"
	SHA384 Algo = "sha384"
	SHA512 Algo = "sha512"
)

// Hash is a parsed SRI hash
type Hash struct {
	Algo   Algo
	Digest []byte
}

// Parse decodes a SRI string like "sha256-<base64>"
func Parse(str string) (*Hash, error) {
	idx := strings.IndexByte(str, '-')
	if idx < 0 {
		return nil, fmt.Errorf("sri: not a hash %s", str)
	}
	algo := Algo(str[:idx])
	switch algo {
	case SHA256, SHA384, SHA512:
	default:
		return nil, fmt.Errorf("sri: unsupported algo %s", algo)
	}
	digest, err := base64.StdEncoding.DecodeString(str[idx+1:])
	if err != nil {
		return nil, err
	}
	return &Hash{Algo: algo, Digest: digest}, nil
}

// NewHasher returns a hash.Hash for the given algo
func NewHasher(algo Algo) hash.Hash {
	switch algo {
	case SHA384:
		return sha512.New384()
	case SHA512:
		return sha512.New()
	default:
		return sha256.New()
	}
}

// String returns the SRI representation of the hash
func (h *Hash) String() string {
	return string(h.Algo) + "-" + base64.StdEncoding.EncodeToString(h.Digest)
}

// Hex returns the hexadecimal representation of the digest
func (h *Hash) Hex() string {
	return fmt.Sprintf("%x", h.Digest)
}
EOF
echo ok"}

