	Private: true,
	Action: actionWithConfig(func(env Env, args []string, config *Config) (err error) {
		if len(args) < 2 {
			return fmt.Errorf("a shell name is required")
		}
		if len(args) < 3 {
			return fmt.Errorf("an envrc path is required")
		}
		if len(args) < 4 {
			return fmt.Errorf("at least one file path is required")
		}

		shellName := args[1]
		shell := DetectShell(shellName)
		if shell == nil {
			return unknownShellError(shellName)
		}

		envrcPath := args[2]
		paths := args[3:]

		for _, path := range paths {
			if filepath.IsAbs(path) {
				msg := "require_allowed: path must be relative: " + path
				fmt.Print("log_error " + BashEscape(msg) + ";\nexit 1;\n")
				return nil
			}
		}

		envrcHash, err := pathHash(envrcPath)
		if err != nil {
			return err
		}
		dbDir := filepath.Join(config.AllowedRequiredDir(), envrcHash)
		envrcDir := filepath.Dir(envrcPath)

		var missing []string
		for _, path := range paths {
			absPath := filepath.Join(envrcDir, path)
			hash, hashErr := fileHash(absPath)
			if hashErr != nil || !fileExists(filepath.Join(dbDir, hash)) {
				missing = append(missing, path)
			}
		}

		if len(missing) == 0 {
			return nil
		}

		e := make(ShellExport)
		e.Add(DIRENV_REQUIRED, strings.Join(missing, ":"))

		verb := "requires"
		if len(missing) > 1 {
			verb = "require"
		}
		msg := fmt.Sprintf("%s %s approval. Run 'direnv allow' to approve.", strings.Join(missing, " and "), verb)

		fmt.Print(shell.Export(e) + "log_error " + BashEscape(msg) + ";\nexit 0;\n")
		return nil
	}),
}
