// CmdFetchURL is `direnv fetchurl <url> [<integrity-hash>]`
var CmdFetchURL = &Cmd{
	Name: "fetchurl",
	Desc: "Fetches a given URL into direnv's CAS",
	Args: []string{"<url>", "[<integrity-hash>]"},
	Action: actionWithConfig(func(env Env, args []string, config *Config) (err error) {
		if len(args) < 2 {
			return fmt.Errorf("missing URL argument")
		}
		url := args[1]

		casDir := config.CASDir()

		var expectedHash string
		if len(args) > 2 {
			expectedHash = args[2]
			hash, err := sri.Parse(expectedHash)
			if err != nil {
				return err
			}
			casPath := filepath.Join(casDir, hash.Hex())
			if fileExists(casPath) {
				fmt.Println(casPath)
				return nil
			}
		}

		if err = os.MkdirAll(casDir, 0755); err != nil {
			return err
		}

		resp, err := http.Get(url)
		if err != nil {
			return err
		}
		defer resp.Body.Close()

		if resp.StatusCode != http.StatusOK {
			return fmt.Errorf("expected status code 200 but got %d", resp.StatusCode)
		}

		tmp, err := os.CreateTemp(casDir, "tmp")
		if err != nil {
			return err
		}
		defer func() {
			if closeErr := tmp.Close(); closeErr != nil {
				fmt.Fprintf(os.Stderr, "Warning: failed to close temp file: %v\n", closeErr)
			}
			if rmErr := os.Remove(tmp.Name()); rmErr != nil {
				fmt.Fprintf(os.Stderr, "Warning: failed to remove temp file %s: %v\n", tmp.Name(), rmErr)
			}
		}()

		hasher := sha256.New()
		if _, err = io.Copy(io.MultiWriter(tmp, hasher), resp.Body); err != nil {
			return err
		}

		hash := &sri.Hash{Algo: sri.SHA256, Digest: hasher.Sum(nil)}
		hashStr := hash.String()

		if expectedHash != "" && expectedHash != hashStr {
			return fmt.Errorf("hash mismatch. Expected '%s' but got '%s'", expectedHash, hashStr)
		}

		casPath := filepath.Join(casDir, hash.Hex())
		if !fileExists(casPath) {
			if err = tmp.Close(); err != nil {
				return err
			}
			// Make the file read-only and executable
			if err = os.Chmod(tmp.Name(), 0500); err != nil {
				return err
			}
			if err = os.Rename(tmp.Name(), casPath); err != nil {
				return err
			}
		}

		if expectedHash != "" {
			fmt.Println(casPath)
		} else if isTerminal(os.Stdout) {
			fmt.Printf("Found hash: %s\n\n", hashStr)
			fmt.Printf("Invoke fetchurl again with the hash as an argument to get the disk location:\n\n")
			fmt.Printf("  direnv fetchurl \"%s\" \"%s\"\n", url, hashStr)
			fmt.Printf("  #=> %s\n", casPath)
		} else {
			fmt.Println(hashStr)
		}

		return nil
	}),
}

// isTerminal returns true if the file is a character device (usually a TTY)
func isTerminal(f *os.File) bool {
	stat, err := f.Stat()
	if err != nil {
		return false
	}
	return stat.Mode()&os.ModeCharDevice != 0
}
