package cmd

import (
	"fmt"
)

// CmdExport is `direnv export $0`
var CmdExport = &Cmd{
	Name: "export",
	Desc: "Loads an .envrc or .env and prints the diff in terms of exports.\n" +
		"Supported SHELL values are: [" + joinShellNames() + "]",
	Args:   []string{"SHELL"},
	Action: actionWithConfig(exportCommand),
}

func exportCommand(env Env, args []string, config *Config) (err error) {
	var (
		shell     Shell
		target    string
		loadedRC  *RC
		toLoad    *RC
		oldEnv    Env
		newEnv    Env
		loadErr   error
		diff      *EnvDiff
		diff2     *EnvDiff
		summary   string
		shellCode string
	)

	pushDebugContext("export")
	logDebug("start")

	if len(args) > 1 {
		target = args[1]
	}

	shell = DetectShell(target)
	if shell == nil {
		return unknownShellError(target)
	}

	// Load the current RC state and look for the RC to load
	logDebug("loading RCs")
	loadedRC = config.LoadedRC()
	if toLoad, err = config.FindRC(); err != nil {
		return err
	}
	if loadedRC == nil && toLoad == nil {
		return nil
	}

	logDebug("updating RC")
	pushDebugContext("update")
	logDebug("Determining action:")
	logDebug("toLoad: %#v", toLoad.pathOrEmpty())
	logDebug("loadedRC: %#v", loadedRC)

	switch {
	case toLoad == nil:
		logDebug("no RC found, unloading")
	case loadedRC == nil:
		logDebug("no RC (implies no DIRENV_DIFF),loading")
	case loadedRC.path != toLoad.path:
		logDebug("new RC, loading")
	case loadedRC.times.Check() != nil:
		logDebug("file changed, reloading")
	default:
		// Nothing changed since the last time, nothing to do
		logDebug("no update needed")
		return nil
	}

	// Restore the environment to its pristine state
	previousEnv := env.Copy()
	if oldEnv, err = config.Revert(previousEnv); err != nil {
		return err
	}
	oldEnv.CleanContext()

	if toLoad == nil {
		logStatus("unloading")
		newEnv = oldEnv.Copy()
	} else {
		// The shell export is generated even if the load failed so that the
		// host shell records that the RC was seen.
		newEnv, loadErr = toLoad.Load(oldEnv)
		if loadErr != nil {
			logDebug("err: %v", loadErr)
		}
	}

	diff = oldEnv.Diff(newEnv)
	if diff.Any() {
		newEnv[DIRENV_DIFF] = diff.Serialize()
	}

	if loadErr == nil && toLoad != nil && !config.HideEnvDiff {
		if summary = diff.Summary(); summary != "" {
			logStatus("export %s", summary)
		}
	}

	diff2 = previousEnv.Diff(newEnv)
	shellCode = diff2.ToShell(shell)

	logDebug("env diff %s", shellCode)
	fmt.Print(shellCode)

	return loadErr
}

// pathOrEmpty returns the path of the RC or an empty string if it is nil
func (rc *RC) pathOrEmpty() string {
	if rc == nil {
		return ""
	}
	return rc.path
}

func joinShellNames() string {
	names := supportedShellNames()
	out := ""
	for i, name := range names {
		if i > 0 {
			out += ", "
		}
		out += name
	}
	return out
}
EOF
